head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[dataList > P > matchIgnoreCase]<br/>getMatched 계열의 메소드에서 조건에 만족하는 값을 비교할때 대소문자를 구분할지 설정합니다.",
    "validation" : [
        "미설정 또는 false 설정 시 getMatched 계열의 메소드에서 값을 비교할때 대소문자를 구분합니다.", // [WAEA-504]
        "true 설정 시 getMatched 계열의 메소드에서 값을 비교할때 대소문자를 구분하지 않습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {   
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        $p.data.remove("target1");
    }

    if (typeof gridView1 !== 'undefined') {
        gridView1.remove();
    }    

    // 조건 설정       
    let properties = {
        matchIgnoreCase: con_matchIgnoreCase.getText(),        
    };    

    let cList = $c.gcm.createCList(properties);

    // // 이벤트 설정
    // let eList = $c.gcm.createEList([""]);       

    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    $c.gcm.createLabel('label="첫번째 컬럼을 대상으로 ab 값 비교하도록 설정된 상태"', '', 'label1');

    strTarget += '<w2:dataList ' + strNameSpace + ' ' + cList + ' id="target1" baseNode="list" repeatNode="map">';        
    strTarget += '<w2:columnInfo>';
    strTarget += '<w2:column id="col1" name="name1" dataType="text"></w2:column>';
    strTarget += '<w2:column id="col2" name="name2" dataType="text"></w2:column>';
    strTarget += '<w2:column id="col3" name="name3" dataType="text"></w2:column>';
    strTarget += '<w2:column id="col4" name="name3" dataType="text"></w2:column>';
    strTarget += '</w2:columnInfo>';
    strTarget += '<w2:data use="true">';
    strTarget += '<w2:row>';
    strTarget += '<col1><![CDATA[ab]]></col1>';
    strTarget += '<col2><![CDATA[col2_1]]></col2>';
    strTarget += '<col3><![CDATA[col3_1]]></col3>';
    strTarget += '<col4><![CDATA[col4_1]]></col4>';
    strTarget += '</w2:row>';
    strTarget += '<w2:row>';
    strTarget += '<col1><![CDATA[AB]]></col1>';
    strTarget += '<col2><![CDATA[col2_2]]></col2>';
    strTarget += '<col3><![CDATA[col3_2]]></col3>';
    strTarget += '<col4><![CDATA[col4_2]]></col4>';
    strTarget += '</w2:row>';
    strTarget += '<w2:row>';
    strTarget += '<col1><![CDATA[Ab]]></col1>';
    strTarget += '<col2><![CDATA[col2_3]]></col2>';
    strTarget += '<col3><![CDATA[col3_3]]></col3>';
    strTarget += '<col4><![CDATA[col4_3]]></col4>';
    strTarget += '</w2:row>';
    strTarget += '<w2:row>';
    strTarget += '<col1><![CDATA[aB]]></col1>';
    strTarget += '<col2><![CDATA[col2_4]]></col2>';
    strTarget += '<col3><![CDATA[col3_4]]></col3>';
    strTarget += '<col4><![CDATA[col4_4]]></col4>';
    strTarget += '</w2:row>';
    strTarget += '</w2:data>';
    strTarget += '</w2:dataList>';     

    // target 생성
    $p.data.create(strTarget);

    // gridView 생성
    $c.gcm.createBasicGridView('dataList="data:target1" rowStatusVisible="true"', '', 'gridView1');

    scwin.btn_getMatchedData_onclick();
}   




scwin.btn_getMatchedData_onclick = function (e) {
    let rtn = '';

    rtn = target1.getMatchedData(0, "ab", true);

    wf_body_bottom.getObj("scwin").setReturnValue("=====getMatchedData 비교 결과=====");

    for (var i=0; i < rtn.length; i++) {                        
        wf_body_bottom.getObj("scwin").setReturnValue(`row[${i}] : ${rtn[i]}`);
    }    
};
